 const userId=session?.user?.id;
 const notify=(m:string)=>{setNotice(m);};
 const loadProfile=useCallback(async()=>{if(!supabase||!userId)return;const {data,error}=await supabase.from('profiles').select('*').eq('id',userId).single();if(error){notify('ما قدرناش نحملو البروفايل: '+prettyError(error));return;}setProfile(data as Profile);setProfileName(data.username);setBio(data.bio||'');},[userId]);
 const loadRooms=useCallback(async()=>{if(!supabase)return;await supabase.rpc('prune_stale_room_members');const {data,error}=await supabase.from('rooms').select('id,code,name,is_private,max_players,status,game_key').eq('status','open').order('last_activity_at',{ascending:false}).limit(30);if(error)notify(prettyError(error));else setRooms((data||[]) as Room[]);},[]);
 const loadLeaderboard=useCallback(async()=>{if(!supabase)return;const {data,error}=await supabase.from('profiles').select('id,username,avatar_url,level,xp,coins,wins,games_played,total_score,equipped_frame,equipped_title,bio,streak_days,last_daily_claim').gt('total_score',0).order('total_score',{ascending:false}).limit(50);if(error)notify(prettyError(error));else setLeaderboard((data||[]).filter((p:any)=>Number(p.total_score)>0) as Profile[]);},[]);
 const loadFriends=useCallback(async()=>{if(!supabase||!userId)return;const {data,error}=await supabase.from('friendships').select('id,requester_id,addressee_id,status,created_at').or('requester_id.eq.'+userId+',addressee_id.eq.'+userId).order('updated_at',{ascending:false});if(error){notify(prettyError(error));return;}const rows=data||[];const ids=[...new Set(rows.flatMap(x=>[x.requester_id,x.addressee_id]).filter(x=>x!==userId))];const {data:ps}=ids.length?await supabase.from('profiles').select('id,username,avatar_url,level,equipped_title').in('id',ids):{data:[]};const mapped=rows.map(x=>({...x,profile:(ps||[]).find(p=>p.id===(x.requester_id===userId?x.addressee_id:x.requester_id))}));setFriends(mapped.filter(x=>x.status==='accepted'));setFriendRequests(mapped.filter(x=>x.status==='pending'&&x.addressee_id===userId));},[userId]);
 const loadShop=useCallback(async()=>{if(!supabase||!userId)return;const [{data:catalog,error},{data:owned,error:ownedError}]=await Promise.all([supabase.from('cosmetic_catalog').select('*').order('price'),supabase.from('player_inventory').select('cosmetic_id').eq('user_id',userId)]);if(error)notify(prettyError(error));else setItems((catalog||[]) as Item[]);if(ownedError)notify(prettyError(ownedError));else setInventory((owned||[]).map(x=>x.cosmetic_id));},[userId]);
 const loadNotifications=useCallback(async()=>{if(!supabase||!userId)return;const {data,error}=await supabase.from('notifications').select('id,kind,title,body,payload,created_at,read_at').eq('user_id',userId).order('created_at',{ascending:false}).limit(30);if(error)notify(prettyError(error));else setNotifications((data||[]) as AppNotification[]);},[userId]);
 const loadDirectMessages=useCallback(async(friendId:string)=>{if(!supabase||!userId)return;const {data,error}=await supabase.from('direct_messages').select('id,sender_id,recipient_id,body,created_at,read_at').or('and(sender_id.eq.'+userId+',recipient_id.eq.'+friendId+'),and(sender_id.eq.'+friendId+',recipient_id.eq.'+userId+')').order('created_at',{ascending:true}).limit(100);if(error){notify(prettyError(error));return;}setDirectMessages((data||[]) as DirectMessage[]);await supabase.from('direct_messages').update({read_at:new Date().toISOString()}).eq('sender_id',friendId).eq('recipient_id',userId).is('read_at',null);},[userId]);
 async function sendDirectMessage(e:FormEvent){e.preventDefault();if(!supabase||!userId||!selectedFriend||!directText.trim())return;const body=directText.trim().slice(0,1500);setDirectText('');const {error}=await supabase.from('direct_messages').insert({sender_id:userId,recipient_id:selectedFriend.profile.id,body});if(error){notify(prettyError(error));setDirectText(body);return;}await loadDirectMessages(selectedFriend.profile.id);}
 async function sendRoomInvite(friend:any){if(!supabase||!userId||!room)return;const {error}=await supabase.from('notifications').insert({user_id:friend.profile.id,actor_id:userId,kind:'room_invite',title:'دعوة للعب',body:(profile?.username||'صديقك')+' دعاك لغرفة '+room.name,payload:{room_id:room.id,room_code:room.code,game_key:room.game_key||selectedGame}});if(error)notify(prettyError(error));else notify('تصيفطات الدعوة لـ '+friend.profile.username);}
 async function markNotificationRead(id:string){if(!supabase)return;await supabase.from('notifications').update({read_at:new Date().toISOString()}).eq('id',id);setNotifications(prev=>prev.map(n=>n.id===id?{...n,read_at:new Date().toISOString()}:n));}
 async function quickMatch(){if(!supabase)return;setBusy(true);const {data,error}=await supabase.rpc('quick_match_room',{p_game_key:quickMode});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(!r){notify('ما لقيناش غرفة مناسبة دابا. حاول مرة أخرى.');return;}setQuickModeOpen(false);await openRoom({id:r.room_id,code:r.room_code,name:r.room_name,is_private:false,max_players:r.max_players,status:'open',game_key:quickMode});}
 const loadDailyMissions=useCallback(async()=>{if(!supabase||!userId)return;const {data,error}=await supabase.rpc('get_daily_missions');if(error)notify(prettyError(error));else setDailyMissions((data||[]) as DailyMission[]);},[userId]);
 useEffect(()=>{const handler=(e:Event)=>{e.preventDefault();setInstallPrompt(e);};window.addEventListener('beforeinstallprompt',handler);return()=>window.removeEventListener('beforeinstallprompt',handler);},[]);
 async function installApp(){if(!installPrompt)return;await installPrompt.prompt();setInstallPrompt(null);}
 async function uploadAvatar(file?:File){if(!file||!supabase||!userId)return;if(!file.type.startsWith('image/')||file.size>5*1024*1024){notify('اختار صورة أقل من 5MB.');return;}setAvatarBusy(true);try{const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=userId+'/'+Date.now()+'.'+ext;const {error:upErr}=await supabase.storage.from('avatars').upload(path,file,{upsert:true,contentType:file.type,cacheControl:'3600'});if(upErr)throw upErr;const {data}=supabase.storage.from('avatars').getPublicUrl(path);const {error}=await supabase.rpc('update_my_profile',{p_username:profileName||profile?.username||session.user.email?.split('@')[0]||'Player',p_bio:bio||'',p_avatar_url:data.publicUrl});if(error)throw error;await loadProfile();notify('تبدلات صورة البروفايل بنجاح.');}catch(e:any){notify(prettyError(e));}finally{setAvatarBusy(false);}}
 useEffect(()=>{if(!supabase)return;supabase.auth.getSession().then(({data})=>setSession(data.session));const {data:{subscription}}=supabase.auth.onAuthStateChange((event,next)=>{setSession(next);if(event==='PASSWORD_RECOVERY')setPasswordRecovery(true);});return()=>subscription.unsubscribe();},[]);
 useEffect(()=>{if(!userId){setProfile(null);setRoom(null);return;}void loadProfile();void loadRooms();void loadLeaderboard();void loadShop();void loadDailyMissions();void loadFriends();},[userId,loadProfile,loadRooms,loadLeaderboard,loadShop,loadDailyMissions]);
 useEffect(()=>{const client=supabase;if(!client||!userId)return;void loadNotifications();const channel=client.channel('mimox-presence',{config:{presence:{key:userId}}});channel.on('presence',{event:'sync'},()=>{const state=channel.presenceState();setOnlineIds(Object.keys(state));}).subscribe(async status=>{if(status==='SUBSCRIBED')await channel.track({user_id:userId,online_at:new Date().toISOString()});});const feed=client.channel('mimox-notifications:'+userId).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'user_id=eq.'+userId},payload=>{const n=payload.new as AppNotification;setNotifications(old=>[n,...old].slice(0,30));notify(n.title+': '+n.body);}).subscribe();return()=>{void client.removeChannel(channel);void client.removeChannel(feed);};},[userId,loadNotifications]);
 useEffect(()=>{const client=supabase;if(!client||!userId||!selectedFriend)return;const friendId=selectedFriend.profile.id;void loadDirectMessages(friendId);const channel=client.channel('dm:'+userId+':'+friendId).on('postgres_changes',{event:'INSERT',schema:'public',table:'direct_messages'},payload=>{const m=payload.new as DirectMessage;if((m.sender_id===userId&&m.recipient_id===friendId)||(m.sender_id===friendId&&m.recipient_id===userId)){setDirectMessages(old=>old.some(x=>x.id===m.id)?old:[...old,m]);if(m.sender_id===friendId)void client.from('direct_messages').update({read_at:new Date().toISOString()}).eq('id',m.id);}}).subscribe();return()=>{void client.removeChannel(channel);};},[userId,selectedFriend?.profile?.id,loadDirectMessages]);

 const authRedirectUrl=()=>window.location.hostname.endsWith('.pages.dev')?'https://mimox-c5a.pages.dev/':window.location.origin+'/';
 async function authSubmit(e:FormEvent){e.preventDefault();if(!supabase)return;setBusy(true);try{const result=authMode==='signup'?await supabase.auth.signUp({email,password,options:{emailRedirectTo:authRedirectUrl(),data:{username:username.trim()}}}):await supabase.auth.signInWithPassword({email,password});if(result.error)notify(prettyError(result.error));else if(authMode==='signup'&&!result.data.session)notify('الحساب تسجل! حل Gmail واضغط رابط التأكيد، غادي يرجعك للموقع المنشور.');}catch(error){notify(prettyError(error));}finally{setBusy(false);}}
 async function signInWithGoogle(){if(!supabase)return;setBusy(true);try{const {error}=await supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:authRedirectUrl()}});if(error)notify(prettyError(error));}catch(error){notify(prettyError(error));}finally{setBusy(false);}}
 async function resendConfirmation(){if(!supabase||!email.trim()){notify('دخل البريد الإلكتروني ديالك أولاً.');return;}setBusy(true);const {error}=await supabase.auth.resend({type:'signup',email:email.trim(),options:{emailRedirectTo:authRedirectUrl()}});setBusy(false);notify(error?prettyError(error):'عاودنا صيفطنا رابط التأكيد. استعمل آخر رسالة وصلاتك.');}
 async function sendPasswordReset(){if(!supabase||!email.trim()){notify('دخل البريد الإلكتروني ديالك أولاً.');return;}setBusy(true);const {error}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:authRedirectUrl()});setBusy(false);notify(error?prettyError(error):'صيفطنا ليك رابط تغيير كلمة السر. شوف Gmail ديالك.');}
 async function saveNewPassword(e:FormEvent){e.preventDefault();if(!supabase||newPassword.length<8)return;setBusy(true);const {error}=await supabase.auth.updateUser({password:newPassword});setBusy(false);if(error){notify(prettyError(error));return;}setPasswordRecovery(false);setNewPassword('');notify('تبدلات كلمة السر بنجاح.');}
 async function signOut(){stopVoice();await supabase?.auth.signOut();setSession(null);setRoom(null);setTab('home');}
 async function sendFriendRequest(e:FormEvent){e.preventDefault();if(!supabase||!friendSearch.trim())return;setFriendBusy(true);const term=friendSearch.trim();let target:any=null;const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;if(uuid.test(term)){const {data}=await supabase.from('profiles').select('id,username').eq('id',term).maybeSingle();target=data;}else{const {data}=await supabase.from('profiles').select('id,username').ilike('username',term).neq('id',userId).maybeSingle();target=data;}if(!target){setFriendBusy(false);notify('ما لقيناش لاعب بهاد الاسم أو ID.');return;}const {error}=await supabase.rpc('send_friend_request',{p_username:target.username});setFriendBusy(false);if(error)notify(prettyError(error));else{setFriendSearch('');notify('تصيفط طلب الصداقة لـ '+target.username);await loadFriends();}}
 async function acceptFriend(id:string){if(!supabase)return;const {data,error}=await supabase.rpc('accept_friend_request',{p_request_id:id});if(error||!data)notify(error?prettyError(error):'الطلب ما بقاش متاح.');else{notify('زدتي صديق جديد.');await loadFriends();}}
 async function removeFriend(id:string){if(!supabase)return;const {error}=await supabase.rpc('remove_friend',{p_friend_id:id});if(error)notify(prettyError(error));else{notify('تحيد الصديق.');await loadFriends();}}
 async function createRoom(){if(!supabase)return;if(privateRoom&&roomPassword.length<4){notify('كلمة السر خاصها تكون 4 حروف على الأقل.');return;}setBusy(true);const {data,error}=await supabase.rpc('create_room',{p_name:roomName,p_private:privateRoom,p_max_players:maxPlayers,p_game_key:selectedGame,p_password:privateRoom?roomPassword:null});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(!r){notify('ما قدرناش نصايبو الغرفة.');return;}setCode(r.room_code);setRoomPassword('');await openRoom({id:r.room_id,code:r.room_code,name:roomName,is_private:privateRoom,max_players:maxPlayers,status:'open',game_key:selectedGame});}
 async function joinRoom(c:string){if(!supabase)return;setBusy(true);const {data,error}=await supabase.rpc('join_room',{p_code:c.trim().toUpperCase(),p_password:joinPassword||null});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(r){setRoomDialog(null);setJoinPassword('');const found=rooms.find(x=>x.code===r.room_code);await openRoom({id:r.room_id,code:r.room_code,name:r.room_name,is_private:found?.is_private||false,max_players:found?.max_players||16,status:'open',game_key:found?.game_key});}}
 async function openRoom(r:Room){setRoom(r);setCode(r.code);setTab('room');await loadRoomData(r.id);}
 async function loadRoomData(id:string){if(!supabase)return;const [{data:members,error:me},{data:chat,error:ce},{data:sessions}]=await Promise.all([supabase.from('room_members').select('user_id,role,last_seen_at').eq('room_id',id),supabase.from('chat_messages').select('id,user_id,body,created_at').eq('room_id',id).order('created_at',{ascending:true}).limit(60),supabase.from('game_sessions').select('id,game_key,status,created_by,result').eq('room_id',id).order('created_at',{ascending:false}).limit(1)]);if(me)notify(prettyError(me));else{const ids=(members||[]).map(m=>m.user_id);const {data:ps}=ids.length?await supabase.from('profiles').select('id,username,avatar_url,level,equipped_frame,equipped_title').in('id',ids):{data:[]};setRoster((members||[]).map(m=>({...m,profile:(ps||[]).find(p=>p.id===m.user_id)})));}if(ce)notify(prettyError(ce));else setMessages(chat||[]);const latest=(sessions||[])[0];if(latest)await loadGame(latest as Game);else{setGame(null);setGamePlayers([]);setGameResult(null);}}
 async function sendMessage(e:FormEvent){e.preventDefault();if(!supabase||!room||!chatText.trim())return;const body=chatText.trim();setChatText('');const {data,error}=await supabase.rpc('send_room_message',{p_room_id:room.id,p_body:body});if(error){notify(prettyError(error));setChatText(body);return;}const {data:row}=await supabase.from('chat_messages').select('id,user_id,body,created_at').eq('id',data).single();if(row)setMessages(prev=>[...prev,row]);}
 async function claimDaily(){if(!supabase)return;setBusy(true);const {data,error}=await supabase.rpc('claim_daily_reward');setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];notify('ربحتي '+r.coins_awarded+' عملة و '+(r.streak%3===0?5:2)+' جواهر و '+r.xp_awarded+' XP! سلسلة '+r.streak+' أيام.');await Promise.all([loadProfile(),loadDailyMissions()]);}
 async function claimMission(m:DailyMission){if(!supabase)return;setBusy(true);const {data,error}=await supabase.rpc('claim_daily_mission',{p_mission_key:m.mission_key});setBusy(false);if(error){notify(prettyError(error));return;}notify('المهمة تكملات! +'+data.coins+' عملة و +'+data.xp+' XP');await Promise.all([loadDailyMissions(),loadProfile()]);}
 async function saveProfile(e:FormEvent){e.preventDefault();if(!supabase)return;setBusy(true);const {error}=await supabase.rpc('update_my_profile',{p_username:profileName.trim(),p_bio:bio.trim(),p_avatar_url:profile?.avatar_url||null});setBusy(false);if(error)notify(prettyError(error));else{notify('تحدّث البروفايل ديالك.');await loadProfile();}}
 async function buyItem(item:Item){if(!supabase)return;setBusy(true);const {error}=await supabase.rpc('purchase_cosmetic',{p_cosmetic_id:item.id});setBusy(false);if(error)notify(prettyError(error));else{notify('شريتي '+item.name);await loadShop();await loadProfile();}}
 async function equipItem(item:Item){if(!supabase)return;const {error}=await supabase.rpc('equip_cosmetic',{p_cosmetic_id:item.id});if(error)notify(prettyError(error));else{notify('تبدلات الزينة ديالك.');await loadProfile();}}
 async function startGame(){if(!supabase||!room)return;setGameResult(null);setBusy(true);const {data,error}=await supabase.rpc('start_party_game',{p_room_id:room.id,p_game_key:selectedGame});setBusy(false);if(error){notify(prettyError(error));return;}await loadGame({id:data,game_key:selectedGame,status:'active',created_by:userId!});}
 async function loadGame(g:Game){if(!supabase)return;setGame(g);setGameResult(g.result||null);const [{data:players,error},{data:secret},{data:actions}]=await Promise.all([supabase.from('game_players').select('user_id,score').eq('session_id',g.id).order('score',{ascending:false}),supabase.rpc('get_my_game_secret',{p_session_id:g.id}),supabase.from('game_actions').select('user_id,action_key').eq('session_id',g.id)]);if(error)notify(prettyError(error));setGamePlayers((players||[]) as Player[]);setGameSecret(secret||{});setGameAction((actions||[]).some(a=>a.user_id===userId)?'sent':'');}
 async function submitAction(action:string,payload:any){if(!supabase||!game)return;setBusy(true);const {error}=await supabase.rpc('submit_party_action',{p_session_id:game.id,p_action_key:action,p_payload:payload});setBusy(false);if(error)notify(prettyError(error));else{notify('وصل الجواب ديالك!');setGameAction('sent');await loadGame(game);}}
 async function finishGame(){if(!supabase||!game)return;setBusy(true);const {data,error}=await supabase.rpc(game.game_key==='impostor'?'finish_impostor_game':'finish_party_game',{p_session_id:game.id});setBusy(false);if(error)notify(prettyError(error));else{setGameResult(data);setGame({...game,status:'completed'});await loadGame({...game,status:'completed'});await loadProfile();await loadLeaderboard();await loadDailyMissions();}}
 async function exitRoom(){if(!supabase||!room)return;stopVoice();await supabase.rpc('leave_room',{p_room_id:room.id});setRoom(null);setGame(null);setTab('home');await loadRooms();}
 useEffect(()=>{const client=supabase;if(!room||!client)return;let active=true;const beat=async()=>{if(document.visibilityState==='hidden')return;const {data,error}=await client.rpc('heartbeat_room',{p_room_id:room.id});if(active&&!error&&!data){notify('الغرفة تسدات أو سالات الجلسة ديالك.');setRoom(null);setTab('rooms');await loadRooms();}};void beat();const timer=window.setInterval(beat,25000);const onVisible=()=>{if(document.visibilityState==='visible')void beat();};document.addEventListener('visibilitychange',onVisible);return()=>{active=false;window.clearInterval(timer);document.removeEventListener('visibilitychange',onVisible);};},[room?.id,loadRooms]);
 useEffect(()=>{if(!gameSecret?.deadline_at){setTimeLeft(10);return;}const update=()=>setTimeLeft(Math.max(0,Math.ceil((new Date(gameSecret.deadline_at).getTime()-Date.now())/1000)));update();const timerId=window.setInterval(update,200);return()=>window.clearInterval(timerId);},[gameSecret?.deadline_at]);
 useEffect(()=>{if(!game||game.status!=='active')return;const poll=window.setInterval(()=>void loadGame(game),2500);return()=>window.clearInterval(poll);},[game?.id,game?.status]);
 useEffect(()=>{if(tab!=='rooms')return;void loadRooms();const timer=window.setInterval(()=>void loadRooms(),20000);return()=>window.clearInterval(timer);},[tab,loadRooms]);
 useEffect(()=>{if(!supabase||!room)return;const ch=supabase.channel('dima-room-feed:'+room.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'chat_messages',filter:'room_id=eq.'+room.id},p=>{const m=p.new as any;setMessages(old=>old.some(x=>x.id===m.id)?old:[...old,m].slice(-60));}).on('postgres_changes',{event:'*',schema:'public',table:'game_sessions',filter:'room_id=eq.'+room.id},()=>void loadRoomData(room.id)).on('postgres_changes',{event:'*',schema:'public',table:'room_members',filter:'room_id=eq.'+room.id},()=>void loadRoomData(room.id)).subscribe();return()=>{void supabase?.removeChannel(ch);};},[room?.id]);

 function stopVoice(){
  if(voiceChannelRef.current&&supabase){void supabase.removeChannel(voiceChannelRef.current);voiceChannelRef.current=null;}
  peerConnectionsRef.current.forEach(pc=>pc.close());peerConnectionsRef.current.clear();
  remoteAudioRef.current.forEach(audio=>{audio.pause();audio.srcObject=null;});remoteAudioRef.current.clear();
  localStreamRef.current?.getTracks().forEach(track=>track.stop());localStreamRef.current=null;
  pendingIceRef.current.clear();setVoiceActive(false);setVoiceMuted(false);setVoiceStatus('الصوت مطفي');
 }
 async function startVoice(){
  if(!supabase||!room||!userId||voiceActive)return;
  if(!navigator.mediaDevices?.getUserMedia){setVoiceStatus('المتصفح ما كيدعمش المايك أو الصفحة ماشي HTTPS.');return;}
  try{
   setVoiceStatus('كنوجد الاتصال الصوتي...');
   let iceServers:RTCIceServer[]=[{urls:['stun:stun.cloudflare.com:3478','stun:stun.l.google.com:19302']}];
   try{const iceResponse=await fetch('https://dima-play-turn-api.m40065744.workers.dev/ice',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'}});if(!iceResponse.ok)throw new Error('TURN غير مهيأ');const iceData=await iceResponse.json();if(Array.isArray(iceData.iceServers)&&iceData.iceServers.length)iceServers=iceData.iceServers;}
   catch{setVoiceStatus('TURN مازال ما تهيّأش؛ غادي نجرب الاتصال المباشر.');}
   const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});
   localStreamRef.current=stream;
   const channel=supabase.channel('voice:'+room.id,{config:{private:true,presence:{key:userId},broadcast:{ack:true}}});
   voiceChannelRef.current=channel;
   const sendSignal=async(to:string,kind:string,data:any)=>{await channel.send({type:'broadcast',event:'signal',payload:{from:userId,to,kind,data}});};
   const makePeer=(peerId:string,initiator:boolean)=>{
    let pc=peerConnectionsRef.current.get(peerId);if(pc)return pc;
    pc=new RTCPeerConnection({iceServers});
    peerConnectionsRef.current.set(peerId,pc);
    stream.getTracks().forEach(track=>pc!.addTrack(track,stream));
    pc.onicecandidate=e=>{if(e.candidate)void sendSignal(peerId,'ice',e.candidate.toJSON());};
    pc.ontrack=e=>{let audio=remoteAudioRef.current.get(peerId);if(!audio){audio=new Audio();audio.autoplay=true;remoteAudioRef.current.set(peerId,audio);}audio.srcObject=e.streams[0];void audio.play().catch(()=>setVoiceStatus('ضغط على الصفحة باش تسمح بالصوت الوارد.'));};
    pc.onconnectionstatechange=()=>{if(pc&&(pc.connectionState==='failed'||pc.connectionState==='closed')){pc.close();peerConnectionsRef.current.delete(peerId);const audio=remoteAudioRef.current.get(peerId);if(audio){audio.pause();audio.srcObject=null;remoteAudioRef.current.delete(peerId);}}};
    if(initiator){void (async()=>{const offer=await pc!.createOffer();await pc!.setLocalDescription(offer);await sendSignal(peerId,'offer',pc!.localDescription);})().catch(()=>setVoiceStatus('فشل إنشاء اتصال صوتي مع لاعب.'));}
    return pc;
   };
   channel.on('broadcast',{event:'signal'},async({payload}:any)=>{
    if(!payload||payload.to!==userId||typeof payload.from!=='string'||payload.from===userId)return;
    try{
     let pc=peerConnectionsRef.current.get(payload.from);
     if(payload.kind==='offer'){pc=makePeer(payload.from,false);await pc.setRemoteDescription(payload.data);const queued=pendingIceRef.current.get(payload.from)||[];for(const candidate of queued)await pc.addIceCandidate(candidate);pendingIceRef.current.delete(payload.from);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await sendSignal(payload.from,'answer',pc.localDescription);}
     else if(payload.kind==='answer'&&pc){await pc.setRemoteDescription(payload.data);const queued=pendingIceRef.current.get(payload.from)||[];for(const candidate of queued)await pc.addIceCandidate(candidate);pendingIceRef.current.delete(payload.from);}
     else if(payload.kind==='ice'&&payload.data){if(pc?.remoteDescription)await pc.addIceCandidate(payload.data);else{const q=pendingIceRef.current.get(payload.from)||[];q.push(payload.data);pendingIceRef.current.set(payload.from,q);}}
    }catch{setVoiceStatus('وقع مشكل فالتفاوض الصوتي. عاود دخل للصوت.');}
   });
   channel.on('presence',{event:'sync'},()=>{
    const state=channel.presenceState() as Record<string,any[]>,ids=new Set<string>();
    Object.values(state).flat().forEach(meta=>{if(typeof meta?.user_id==='string'&&meta.user_id!==userId)ids.add(meta.user_id);});
    const peers=[...ids].sort().slice(0,5);
    for(const [id,pc] of peerConnectionsRef.current){if(!peers.includes(id)){pc.close();peerConnectionsRef.current.delete(id);const audio=remoteAudioRef.current.get(id);if(audio){audio.pause();audio.srcObject=null;remoteAudioRef.current.delete(id);}}}
    if(ids.size>5)setVoiceStatus('الغرفة الصوتية كتقبل 6 مشاركين كحد أقصى فهاد النسخة.');
    else setVoiceStatus('الصوت خدام — '+(ids.size+1)+' مشاركين');
    peers.forEach(id=>{if(userId<id)makePeer(id,true);});
   });
   channel.subscribe(async(status:string)=>{
    if(status==='SUBSCRIBED'){await channel.track({user_id:userId,joined_at:new Date().toISOString()});setVoiceActive(true);setVoiceStatus('الميك خدام. استعمل زر الكتم إلا بغيتي.');}
    else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'){setVoiceStatus('تعذر الاتصال الصوتي. راجع صلاحيات Realtime.');stopVoice();}
   });
  }catch(e:any){setVoiceStatus(e?.name==='NotAllowedError'?'خاصك تسمح باستعمال المايك.':e?.message||'تعذر تشغيل المايك.');stopVoice();}
 }
 function toggleVoiceMute(){const next=!voiceMuted;localStreamRef.current?.getAudioTracks().forEach(track=>track.enabled=!next);setVoiceMuted(next);}
 useEffect(()=>()=>stopVoice(),[room?.id]);
